package com.vandorlabs.neoforge.screen;
import com.vandorlabs.screen.ScreenArtworkMigration;
import com.vandorlabs.neoforge.ModernHousingTags;
import net.minecraft.nbt.*;
/** Actual full source catalog supplies reference policy; native NBT runs the same migrated cases. */
public final class ScreenArtworkChecks {
 public static void main(String[] args)throws Exception{com.google.gson.JsonObject source;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenArtworkReference")))){source=com.google.gson.JsonParser.parseReader(reader).getAsJsonObject();}var choices=source.getAsJsonArray("choices");NativeScreenCatalog catalog=NativeScreenCatalog.INSTANCE;java.util.List<String> screens=new java.util.ArrayList<>(),inputs=new java.util.ArrayList<>();for(var id:source.getAsJsonArray("screens"))screens.add(id.getAsString());for(var id:source.getAsJsonArray("inputs"))inputs.add(id.getAsString());if(!catalog.screens().equals(screens)||!catalog.inputs().equals(inputs)||catalog.defaultHousing()!=source.get("defaultHousing").getAsInt()||catalog.defaultFrame()!=source.get("frame").getAsInt())throw new AssertionError("Native catalog names/defaults differ from actual source");for(var entry:source.getAsJsonObject("sources").entrySet())if(catalog.sourceChoice(entry.getKey())!=entry.getValue().getAsInt())throw new AssertionError("Native source artwork choice "+entry.getKey());for(var entry:source.getAsJsonObject("screenAliases").entrySet())if(!catalog.canonicalScreen(entry.getKey()).equals(entry.getValue().getAsString()))throw new AssertionError("Native screen alias "+entry.getKey());for(var entry:source.getAsJsonObject("inputAliases").entrySet())if(!catalog.canonicalInput(entry.getKey()).equals(entry.getValue().getAsString()))throw new AssertionError("Native input alias "+entry.getKey());for(var entry:source.getAsJsonObject("inputFrames").entrySet())if(catalog.inputFrames(entry.getKey())!=entry.getValue().getAsInt())throw new AssertionError("Native input timing "+entry.getKey());if(catalog.options().size()!=source.getAsJsonArray("options").size())throw new AssertionError("Source option coverage");for(var option:source.getAsJsonArray("options")){var expected=option.getAsJsonObject();var actual=catalog.options().stream().filter(candidate->candidate.key().equals(expected.get("key").getAsString())).findFirst().orElseThrow();if(!actual.bare().equals(expected.get("bareId").getAsString())||!actual.framed().equals(expected.get("framedId").getAsString()))throw new AssertionError("Source option pairing");}java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;
  for(var id:source.getAsJsonArray("ids"))for(String field:new String[]{"selectedScreen","inputPanel","secondaryInputPanel"})for(int front=0;front<3;front++){CompoundTag tag=new CompoundTag();tag.putString(field,id.getAsString());tag.putString("Foreign","retained");if(front==1)tag.putInt("FrameFront",-1);if(front==2)tag.putString("FrameFront","future");digest(hash,tag,catalog);cases++;}
  for(int choice=-4;choice<choices.size();choice++)for(String field:new String[]{"PrimarySurfaceTexture","SecondarySurfaceTexture"}){CompoundTag tag=new CompoundTag();tag.putInt(field,choice);digest(hash,tag,catalog);cases++;}StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("94527eaa6d795c6fe784c5d5c639a8506aec23b336488332d1ecf2b966f09d49"))throw new AssertionError("Native artwork differs from source "+out);System.out.println("Native Screen artwork migration parity PASS cases="+cases+" sha256="+out);}
 private static void digest(java.security.MessageDigest hash,CompoundTag tag,ScreenArtworkMigration.Catalog catalog)throws Exception{CompoundTag original=tag.copy();boolean needed=ScreenArtworkMigration.needed(new ModernHousingTags(tag),catalog);CompoundTag normalized=NativeScreenArtworkMigration.normalize(tag,catalog);if(!tag.equals(original))throw new AssertionError("Native migration mutated original");boolean changed=!normalized.equals(tag);hash.update((needed+":"+changed+":"+canonical(normalized)).getBytes("UTF-8"));}
 private static String canonical(CompoundTag tag){StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(tag.getAllKeys()))out.append(key).append(':').append(tag.get(key)).append(';');return out.append('}').toString();}
}
